type Command interface{ Execute(ctx context.Context) error }

var registry = map[string]func() Command{"render": func() Command { return &RenderCmd{} }}

func Invoke(ctx context.Context, kind string, payload json.RawMessage) error {
    newCmd, ok := registry[kind]        // allow-list: unknown tags never reach a decoder
    if !ok {
        return fmt.Errorf("unknown command %q", kind)
    }
    c := newCmd()
    if err := json.Unmarshal(payload, c); err != nil {
        return err
    }
    return c.Execute(ctx)
}
